    51	        app.get("/reservations/{id}", reservationController::getReservation);
    52	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
    53	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
    54	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
    55	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
    56	        app.get("/reservations/{id}/document", reservationController::getDocument);
    57	        app.get("/messages", messageController::getMessages);
    58	        app.get("/reports/occupancy", reportController::getOccupancyReport);
    59	        app.get("/reports/revenue", reportController::getRevenueReport);
    60	
