    62	            ctx.status(HttpStatus.BAD_REQUEST)
    63	               .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    64	        });
    65	
    66	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
