    74	        });
    75	
    76	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
    77	            ctx.status(HttpStatus.CONFLICT)
    78	               .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    79	        });
    80	
    81	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
    82	            ctx.status(HttpStatus.CONFLICT)
    83	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
    84	        });
    85	
    86	        app.exception(CapacityExceededException.class, (e, ctx) -> {
    87	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
    88	               .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    89	        });
    90	
    91	        app.exception(Exception.class, (e, ctx) -> {
    92	            e.printStackTrace();
    93	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR)
    94	               .json(new ErrorResponse("INTERNAL_ERROR", "An internal error occurred"));
    95	        });
    96	
    97	        app.start(port);
    98	        System.out.println("Pousada Maré Alta running on port " + port);
    99	    }
