    15	
    16	public class ReservationController {
    17	    private final ReservationService reservationService;
    18	
    19	    public ReservationController(ReservationService reservationService) {
    20	        this.reservationService = reservationService;
    21	    }
    22	
    23	    public void createReservation(Context ctx) {
    24	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    25	
    26	        validateRequest(request);
    27	
    28	        GuestIdentification identification = parseIdentification(request);
    29	        LocalDate checkIn = parseDate(request.checkIn());
    30	        LocalDate checkOut = parseDate(request.checkOut());
    31	        RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
    32	
    33	        Reservation reservation = reservationService.createReservation(
    34	            request.roomNumber(),
    35	            request.guestName(),
    36	            request.guestEmail(),
    37	            identification,
    38	            checkIn,
    39	            checkOut,
    40	            request.guests(),
    41	            ratePlan
    42	        );
    43	
    44	        ctx.status(201).json(ReservationDto.from(reservation));
    45	    }
    46	
    47	    public void getReservation(Context ctx) {
    48	        long id = ctx.pathParamAsClass("id", Long.class).get();
    49	        Reservation reservation = reservationService.getReservation(id);
    50	        ctx.json(ReservationDto.from(reservation));
    51	    }
    52	
    53	    public void confirmReservation(Context ctx) {
    54	        long id = ctx.pathParamAsClass("id", Long.class).get();
    55	        Reservation reservation = reservationService.confirmReservation(id);
    56	        ctx.json(ReservationDto.from(reservation));
    57	    }
    58	
    59	    public void cancelReservation(Context ctx) {
    60	        long id = ctx.pathParamAsClass("id", Long.class).get();
    61	        Reservation reservation = reservationService.cancelReservation(id);
    62	        ctx.json(ReservationDto.from(reservation));
    63	    }
    64	
    65	    public void checkIn(Context ctx) {
    66	        long id = ctx.pathParamAsClass("id", Long.class).get();
    67	        Reservation reservation = reservationService.checkIn(id);
    68	        ctx.json(ReservationDto.from(reservation));
    69	    }
    70	
    71	    public void checkOut(Context ctx) {
    72	        long id = ctx.pathParamAsClass("id", Long.class).get();
    73	        Reservation reservation = reservationService.checkOut(id);
    74	        ctx.json(DocumentDto.from(reservation));
    75	    }
    76	
    77	    public void getDocument(Context ctx) {
    78	        long id = ctx.pathParamAsClass("id", Long.class).get();
    79	        Reservation reservation = reservationService.getReservation(id);
    80	
    81	        if (!reservation.isPaid()) {
    82	            throw new InvalidRequestException("Document is only available for paid reservations");
    83	        }
    84	
    85	        ctx.json(DocumentDto.from(reservation));
    86	    }
    87	
    88	    private void validateRequest(CreateReservationRequest request) {
    89	        if (request.roomNumber() == null || request.guestName() == null ||
    90	            request.guestEmail() == null || request.checkIn() == null ||
    91	            request.checkOut() == null || request.ratePlan() == null) {
    92	            throw new InvalidRequestException("Missing required fields");
    93	        }
    94	
    95	        if (request.guests() < 1) {
    96	            throw new InvalidRequestException("At least one guest is required");
    97	        }
    98	    }
    99	
   100	    private GuestIdentification parseIdentification(CreateReservationRequest request) {
   101	        boolean hasCpf = request.guestCpf() != null;
   102	        boolean hasCnpj = request.companyCnpj() != null && request.companyName() != null;
   103	        boolean hasPassport = request.guestPassport() != null && request.guestCountry() != null;
   104	
   105	        int count = (hasCpf ? 1 : 0) + (hasCnpj ? 1 : 0) + (hasPassport ? 1 : 0);
   106	        if (count != 1) {
   107	            throw new InvalidRequestException("Exactly one type of identification is required");
   108	        }
   109	
   110	        if (hasCpf) {
   111	            return new GuestIdentification.Cpf(request.guestCpf());
   112	        } else if (hasCnpj) {
   113	            return new GuestIdentification.Cnpj(request.companyCnpj(), request.companyName());
   114	        } else {
   115	            return new GuestIdentification.Passport(request.guestPassport(), request.guestCountry());
   116	        }
   117	    }
   118	
   119	    private LocalDate parseDate(String date) {
   120	        try {
   121	            return LocalDate.parse(date);
   122	        } catch (DateTimeParseException e) {
   123	            throw new InvalidRequestException("Invalid date format: " + date);
   124	        }
   125	    }
   126	}
