     1	package com.pousada.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        Month month = date.getMonth();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == Month.DECEMBER && day >= 15) {
    16	            return true;
    17	        }
    18	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    19	            return true;
    20	        }
    21	        return month == Month.JULY;
    22	    }
    23	
    24	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate night) {
    25	        BigDecimal price = baseRate;
    26	        if (isHighSeason(night)) {
    27	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
    28	        }
    29	        return round(price);
    30	    }
    31	
    32	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    33	        BigDecimal subtotal = BigDecimal.ZERO;
    34	        LocalDate current = checkIn;
    35	        while (current.isBefore(checkOut)) {
    36	            subtotal = subtotal.add(calculateNightPrice(baseRate, current));
    37	            current = current.plusDays(1);
    38	        }
    39	        return round(subtotal);
    40	    }
    41	
    42	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    43	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
    44	        return round(discount);
    45	    }
    46	
    47	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    48	        return round(subtotal.subtract(discount));
    49	    }
    50	
    51	    public static BigDecimal round(BigDecimal value) {
    52	        return value.setScale(2, RoundingMode.HALF_EVEN);
    53	    }
    54	}
