    18	    private final int nights;
    19	    private final BigDecimal subtotal;
    20	    private final BigDecimal discount;
    21	    private final BigDecimal total;
    22	    private ReservationStatus status;
    23	    private BigDecimal amountPaid;
    24	    private BigDecimal refund;
    25	
    26	    public Reservation(String roomNumber, String guestName, String guestEmail,
    27	                      GuestIdentification identification, LocalDate checkIn, LocalDate checkOut,
    28	                      int guests, RatePlan ratePlan, BigDecimal nightlyRate) {
    29	        this.roomNumber = roomNumber;
    30	        this.guestName = guestName;
    31	        this.guestEmail = guestEmail;
    32	        this.identification = identification;
    33	        this.checkIn = checkIn;
    34	        this.checkOut = checkOut;
    35	        this.guests = guests;
    36	        this.ratePlan = ratePlan;
    37	        this.nightlyRate = nightlyRate;
    38	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    39	        this.subtotal = PricingCalculator.calculateSubtotal(nightlyRate, checkIn, checkOut);
    40	        this.discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
    41	        this.total = PricingCalculator.calculateTotal(subtotal, discount);
    42	        this.status = ReservationStatus.PENDING;
    43	        this.amountPaid = BigDecimal.ZERO;
    44	        this.refund = null;
    45	    }
    46	
    47	    public void confirm() {
    48	        if (status != ReservationStatus.PENDING) {
    49	            throw new IllegalStateException("Can only confirm pending reservations");
    50	        }
    51	        this.status = ReservationStatus.CONFIRMED;
    52	        this.amountPaid = this.total;
    53	    }
    54	
    55	    public void checkIn() {
    56	        if (status != ReservationStatus.CONFIRMED) {
    57	            throw new IllegalStateException("Can only check in confirmed reservations");
    58	        }
    59	        this.status = ReservationStatus.CHECKED_IN;
    60	    }
    61	
    62	    public void checkOut() {
    63	        if (status != ReservationStatus.CHECKED_IN) {
    64	            throw new IllegalStateException("Can only check out checked-in reservations");
    65	        }
    66	        this.status = ReservationStatus.CHECKED_OUT;
    67	    }
    68	
    69	    public void cancel() {
    70	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
    71	            throw new IllegalStateException("Can only cancel pending or confirmed reservations");
    72	        }
    73	        this.status = ReservationStatus.CANCELLED;
    74	
    75	        if (ratePlan == RatePlan.STANDARD && amountPaid.compareTo(BigDecimal.ZERO) > 0) {
    76	            this.refund = amountPaid;
    77	        } else {
    78	            this.refund = BigDecimal.ZERO;
