    26	    public Reservation(String roomNumber, String guestName, String guestEmail,
    27	                      GuestIdentification identification, LocalDate checkIn, LocalDate checkOut,
    28	                      int guests, RatePlan ratePlan, BigDecimal nightlyRate) {
    29	        this.roomNumber = roomNumber;
