    22	            VALUES (?, ?, ?, ?)
    23	            RETURNING id
    24	            """;
    25	
    26	        try (Connection conn = database.getConnection();
    27	             PreparedStatement stmt = conn.prepareStatement(sql)) {
    28	
    29	            stmt.setString(1, message.getChannel());
    30	            stmt.setString(2, message.getTo());
    31	            stmt.setString(3, message.getSubject());
    32	            stmt.setString(4, message.getBody());
    33	
    34	            try (ResultSet rs = stmt.executeQuery()) {
    35	                if (rs.next()) {
    36	                    message.setId(rs.getLong("id"));
    37	                }
    38	            }
    39	        } catch (SQLException e) {
    40	            throw new RuntimeException("Failed to save message", e);
    41	        }
    42	
    43	        return message;
