   222	    private Reservation mapReservation(ResultSet rs) throws SQLException {
   223	        GuestIdentification identification;
   224	        String guestCpf = rs.getString("guest_cpf");
   225	        String companyCnpj = rs.getString("company_cnpj");
   226	        String guestPassport = rs.getString("guest_passport");
