   178	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
   179	        stmt.setString(1, reservation.getRoomNumber());
   180	        stmt.setString(2, reservation.getGuestName());
   181	        stmt.setString(3, reservation.getGuestEmail());
   182	
   183	        GuestIdentification id = reservation.getIdentification();
   184	        if (id instanceof GuestIdentification.Cpf cpf) {
   185	            stmt.setString(4, cpf.cpf());
   186	            stmt.setNull(5, Types.VARCHAR);
   187	            stmt.setNull(6, Types.VARCHAR);
   188	            stmt.setNull(7, Types.VARCHAR);
   189	            stmt.setNull(8, Types.VARCHAR);
   190	        } else if (id instanceof GuestIdentification.Cnpj cnpj) {
   191	            stmt.setNull(4, Types.VARCHAR);
   192	            stmt.setString(5, cnpj.cnpj());
   193	            stmt.setString(6, cnpj.companyName());
   194	            stmt.setNull(7, Types.VARCHAR);
   195	            stmt.setNull(8, Types.VARCHAR);
   196	        } else if (id instanceof GuestIdentification.Passport passport) {
   197	            stmt.setNull(4, Types.VARCHAR);
   198	            stmt.setNull(5, Types.VARCHAR);
   199	            stmt.setNull(6, Types.VARCHAR);
   200	            stmt.setString(7, passport.passport());
   201	            stmt.setString(8, passport.country());
   202	        }
   203	
   204	        stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
   205	        stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
   206	        stmt.setInt(11, reservation.getGuests());
   207	        stmt.setString(12, reservation.getRatePlan().name());
   208	        stmt.setBigDecimal(13, reservation.getNightlyRate());
   209	        stmt.setInt(14, reservation.getNights());
   210	        stmt.setBigDecimal(15, reservation.getSubtotal());
   211	        stmt.setBigDecimal(16, reservation.getDiscount());
   212	        stmt.setBigDecimal(17, reservation.getTotal());
   213	        stmt.setString(18, reservation.getStatus().name());
   214	        stmt.setBigDecimal(19, reservation.getAmountPaid());
   215	        if (reservation.getRefund() != null) {
   216	            stmt.setBigDecimal(20, reservation.getRefund());
   217	        } else {
   218	            stmt.setNull(20, Types.DECIMAL);
   219	        }
   220	    }
   221	
   222	    private Reservation mapReservation(ResultSet rs) throws SQLException {
   223	        GuestIdentification identification;
   224	        String guestCpf = rs.getString("guest_cpf");
   225	        String companyCnpj = rs.getString("company_cnpj");
   226	        String guestPassport = rs.getString("guest_passport");
   227	
   228	        if (guestCpf != null) {
   229	            identification = new GuestIdentification.Cpf(guestCpf);
   230	        } else if (companyCnpj != null) {
   231	            String companyName = rs.getString("company_name");
   232	            identification = new GuestIdentification.Cnpj(companyCnpj, companyName);
   233	        } else {
   234	            String guestCountry = rs.getString("guest_country");
   235	            identification = new GuestIdentification.Passport(guestPassport, guestCountry);
   236	        }
   237	
   238	        Reservation reservation = new Reservation(
   239	            rs.getString("room_number"),
   240	            rs.getString("guest_name"),
   241	            rs.getString("guest_email"),
   242	            identification,
   243	            rs.getDate("check_in").toLocalDate(),
   244	            rs.getDate("check_out").toLocalDate(),
   245	            rs.getInt("guests"),
   246	            RatePlan.valueOf(rs.getString("rate_plan")),
   247	            rs.getBigDecimal("nightly_rate")
   248	        );
   249	
   250	        reservation.setId(rs.getLong("id"));
   251	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
   252	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
   253	        BigDecimal refund = rs.getBigDecimal("refund");
   254	        if (!rs.wasNull()) {
   255	            reservation.setRefund(refund);
   256	        }
   257	
   258	        return reservation;
   259	    }
   260	}
